<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {api} from './api'
const props=defineProps({channel:{type:String,default:'both'}})
const campaigns=ref([]),selected=ref(null),fields=ref([]),error=ref(''),success=ref(''),saving=ref(false),questionSaving=ref(false),questionEditorOpen=ref(false),expandedQuestions=ref(new Set())
const form=reactive({name:'',description:'',status:'draft',channel_scope:'both'})
const q=reactive({id:null,question_text:'',title:'',answer_key:'',reply_type:'text',required:true,capture_field_id:'',config:{choices:[]}})
const choiceMode=computed(()=>q.reply_type==='choice'||q.reply_type==='multiple_choice')
function resetQ(close=false){Object.assign(q,{id:null,question_text:'',title:'',answer_key:'',reply_type:'text',required:true,capture_field_id:'',config:{choices:[]}});if(close)questionEditorOpen.value=false}
function newQuestion(){resetQ();questionEditorOpen.value=true;error.value='';success.value=''}
function toggleQuestion(id){const next=new Set(expandedQuestions.value);next.has(id)?next.delete(id):next.add(id);expandedQuestions.value=next}
async function load(){try{[campaigns.value,fields.value]=await Promise.all([api.campaigns(),api.contactFields()])}catch(e){error.value=e.message}}
async function open(item){try{selected.value=await api.campaign(item.id);Object.assign(form,{name:selected.value.name,description:selected.value.description||'',status:selected.value.status,channel_scope:selected.value.channel_scope});resetQ(true);error.value='';success.value=''}catch(e){error.value=e.message}}
async function refreshSelected(){if(!selected.value)return;selected.value=await api.campaign(selected.value.id);const i=campaigns.value.findIndex(x=>x.id===selected.value.id);if(i>=0)campaigns.value[i]={...campaigns.value[i],...selected.value,question_count:selected.value.questions?.length||0}}
async function createCampaign(){const name=prompt('Campaign name');if(!name)return;try{const row=await api.createCampaign({name,description:'',status:'draft',channel_scope:props.channel==='telegram'?'telegram':props.channel==='whatsapp'?'whatsapp':'both'});campaigns.value.push(row);await open(row);success.value='Campaign created and saved.'}catch(e){error.value=e.message}}
async function saveCampaign(){if(!selected.value)return;saving.value=true;error.value='';try{selected.value=await api.updateCampaign(selected.value.id,{...form});Object.assign(form,{name:selected.value.name,description:selected.value.description||'',status:selected.value.status,channel_scope:selected.value.channel_scope});const i=campaigns.value.findIndex(x=>x.id===selected.value.id);if(i>=0)campaigns.value[i]={...campaigns.value[i],...selected.value};success.value='Campaign saved successfully.'}catch(e){error.value=e.message}finally{saving.value=false}}
function editQuestion(item){Object.assign(q,{id:item.id,question_text:item.question_text,title:item.title||'',answer_key:item.answer_key||'',reply_type:item.reply_type||'text',required:item.required!==false,capture_field_id:item.capture_field_id||'',config:JSON.parse(JSON.stringify(item.config||{}))});if(!Array.isArray(q.config.choices))q.config.choices=[];questionEditorOpen.value=true;error.value='';success.value=''}
function addChoice(){q.config.choices.push({label:'',value:''})}
async function saveQuestion(){error.value='';success.value='';if(!selected.value){error.value='Select a campaign first.';return}if(!q.question_text.trim()){error.value='Please enter the question text.';return}if(choiceMode.value&&(!q.config.choices?.length||q.config.choices.some(c=>!String(c.label||'').trim()||!String(c.value||'').trim()))){error.value='Multiple choice questions need at least one choice, and every choice needs a label and stored value.';return}questionSaving.value=true;const payload={question_text:q.question_text.trim(),title:q.title||null,answer_key:q.answer_key||null,reply_type:q.reply_type,required:q.required,capture_field_id:q.capture_field_id?Number(q.capture_field_id):null,config:q.config};try{const wasEditing=!!q.id;const saved=q.id?await api.updateCampaignQuestion(selected.value.id,q.id,payload):await api.addCampaignQuestion(selected.value.id,payload);await refreshSelected();if(!selected.value.questions?.some(item=>item.id===saved.id))throw new Error('The server accepted the question but it was not returned by the campaign. Please refresh and try again.');expandedQuestions.value=new Set([...expandedQuestions.value,saved.id]);resetQ(true);success.value=wasEditing?'Question updated successfully.':'Question saved successfully. Click “+ Add question” to add the next one.'}catch(e){error.value=e.message}finally{questionSaving.value=false}}
async function removeQuestion(item){if(!confirm(`Delete “${item.question_text}”?`))return;try{await api.deleteCampaignQuestion(selected.value.id,item.id);await refreshSelected();success.value='Question deleted.'}catch(e){error.value=e.message}}
async function move(item,delta){const list=[...selected.value.questions],i=list.findIndex(x=>x.id===item.id),j=i+delta;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];try{selected.value.questions=await api.reorderCampaignQuestions(selected.value.id,list.map(x=>x.id));success.value='Question order saved.'}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="campaign-page"><header><div><p class="eyebrow">Reusable questionnaires</p><h1>Campaigns</h1><p>Create a questionnaire once and run it from any WhatsApp or Telegram flow.</p></div><button type="button" class="primary" @click="createCampaign">+ New campaign</button></header><div v-if="error" class="notice error">{{error}}</div><div v-if="success" class="notice">{{success}}</div><div class="campaign-layout"><aside><button type="button" v-for="item in campaigns" :key="item.id" :class="{active:selected?.id===item.id}" @click="open(item)"><b>{{item.name}}</b><span>{{item.question_count}} questions · {{item.status}}</span></button><p v-if="!campaigns.length">No campaigns yet.</p></aside><main v-if="selected"><div class="card campaign-meta"><label>Name<input v-model="form.name"></label><label>Description<textarea v-model="form.description" rows="2"></textarea></label><div class="two"><label>Status<select v-model="form.status"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option></select></label><label>Channels<select v-model="form.channel_scope"><option value="both">WhatsApp + Telegram</option><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option></select></label></div><button type="button" class="primary" :disabled="saving" @click="saveCampaign">{{saving?'Saving…':'Save campaign'}}</button></div><div class="questions"><div class="questions-head"><div><h2>Questions</h2><p>{{selected.questions?.length||0}} question{{selected.questions?.length===1?'':'s'}} in this campaign</p></div><button type="button" class="primary" @click="newQuestion">+ Add question</button></div><div v-if="!selected.questions?.length" class="empty-questions">No questions yet. Click <b>+ Add question</b> to create the first one.</div><article v-for="item in selected.questions" :key="item.id" :class="{expanded:expandedQuestions.has(item.id)}"><button type="button" class="question-summary" @click="toggleQuestion(item.id)"><span class="order">{{item.sort_order}}</span><span class="summary-copy"><b>{{item.question_text}}</b><small>{{item.reply_type}} · %input.{{item.answer_key}}%</small></span><span class="chevron">{{expandedQuestions.has(item.id)?'⌃':'⌄'}}</span></button><div v-if="expandedQuestions.has(item.id)" class="question-detail"><dl><div><dt>Answer key</dt><dd>%input.{{item.answer_key}}%</dd></div><div><dt>Reply type</dt><dd>{{item.reply_type}}</dd></div><div><dt>Required</dt><dd>{{item.required?'Yes':'No'}}</dd></div></dl><div v-if="item.config?.choices?.length" class="saved-choices"><b>Choices</b><span v-for="(choice,i) in item.config.choices" :key="i">{{choice.label}} → {{choice.value}}</span></div><div class="row-actions"><button type="button" @click="move(item,-1)">↑ Move up</button><button type="button" @click="move(item,1)">↓ Move down</button><button type="button" @click="editQuestion(item)">Edit</button><button type="button" class="danger" @click="removeQuestion(item)">Delete</button></div></div></article></div><form v-if="questionEditorOpen" class="card question-editor" @submit.prevent="saveQuestion"><div class="editor-head"><h2>{{q.id?'Edit question':'Add question'}}</h2><button type="button" class="close" @click="resetQ(true)">×</button></div><label>Question<input v-model="q.question_text" placeholder="Have you greeted the manager?"></label><div class="two"><label>Answer key<input v-model="q.answer_key" placeholder="greeted_manager"><small>Leave blank to generate it from the question.</small></label><label>Reply type<select v-model="q.reply_type"><option value="text">Text</option><option value="email">Email address</option><option value="phone">Phone number (typed)</option><option value="telegram_phone">Telegram — Share phone number</option><option value="date">Date</option><option value="number">Number</option><option value="integer">Whole number</option><option value="decimal">Decimal number</option><option value="image">Photo / image</option><option value="audio">Audio / voice note</option><option value="video">Video</option><option value="document">Document / file</option><option value="sticker">Sticker</option><option value="media">Any media</option><option value="choice">Multiple choice</option></select></label></div><label class="check"><input v-model="q.required" type="checkbox"> Reply required</label><label>Save valid reply to<select v-model="q.capture_field_id"><option value="">Do not save reply</option><option v-for="f in fields" :key="f.id" :value="f.id">{{f.label||f.name||f.key}}</option></select></label><div v-if="choiceMode" class="choice-box"><div class="choice-title"><b>Choices</b><button type="button" @click="addChoice">+ Add choice</button></div><div v-for="(choice,i) in q.config.choices" :key="i" class="choice-row"><input v-model="choice.label" placeholder="Label, e.g. Yes"><input v-model="choice.value" placeholder="Stored value, e.g. yes"><button type="button" @click="q.config.choices.splice(i,1)">×</button></div><p v-if="!q.config.choices.length">Add at least one choice.</p></div><div class="actions"><button type="submit" class="primary save-question" :disabled="questionSaving">{{questionSaving?'Saving…':q.id?'Update question':'Save question'}}</button><button type="button" @click="resetQ(true)">Cancel</button></div></form></main><div v-else class="empty">Select a campaign or create a new one.</div></div></section></template>
<style scoped>.campaign-page{margin-left:220px;min-height:100vh;padding:32px 38px;background:#f4f7f6}.campaign-page>header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px}.campaign-page h1{margin:2px 0 5px;font-size:30px}.campaign-page header p:last-child{margin:0;color:#74867e}.eyebrow{margin:0;text-transform:uppercase;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em}.primary{border:0;background:#168653;color:white;border-radius:8px;padding:10px 14px;font-weight:700;cursor:pointer}.primary:disabled{opacity:.6}.campaign-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:20px}.campaign-layout>aside{display:flex;flex-direction:column;gap:7px}.campaign-layout>aside button{text-align:left;border:1px solid #dce5e1;background:#fff;border-radius:10px;padding:12px}.campaign-layout>aside button.active{border-color:#168653;background:#f2fbf6}.campaign-layout>aside b,.campaign-layout>aside span{display:block}.campaign-layout>aside span{font-size:11px;color:#778981;margin-top:4px}.card{background:#fff;border:1px solid #dfe7e3;border-radius:13px;padding:18px;margin-bottom:18px}.card label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:700;margin-bottom:12px}.card label small{font-weight:400;color:#7b8d85}.card input,.card textarea,.card select{border:1px solid #d5e0db;border-radius:8px;padding:9px;background:#fff}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.questions{margin-bottom:18px}.questions-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.questions-head h2,.question-editor h2{font-size:18px;margin:0}.questions-head p{margin:3px 0 0;color:#7b8d85;font-size:12px}.questions article{background:#fff;border:1px solid #dfe7e3;border-radius:10px;margin-bottom:7px;overflow:hidden}.questions article.expanded{border-color:#b8d7c8}.question-summary{width:100%;display:grid;grid-template-columns:34px minmax(0,1fr) 30px;align-items:center;gap:8px;text-align:left;border:0;background:#fff;padding:12px;cursor:pointer}.summary-copy b,.summary-copy small{display:block}.summary-copy small{color:#7b8d85;margin-top:3px}.chevron{text-align:center;color:#678076}.question-detail{border-top:1px solid #e4ebe7;padding:14px 16px;background:#fbfdfc}.question-detail dl{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:0 0 12px}.question-detail dl div{min-width:0}.question-detail dt{font-size:10px;text-transform:uppercase;color:#809188;font-weight:800}.question-detail dd{margin:3px 0 0;font-size:12px;overflow-wrap:anywhere}.saved-choices{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin-bottom:12px}.saved-choices span{background:#eef6f2;border-radius:6px;padding:5px 8px;font-size:11px}.row-actions{display:flex;gap:7px;flex-wrap:wrap}.row-actions button,.actions button,.choice-title button,.choice-row button{border:1px solid #d6e0dc;background:#fff;border-radius:7px;padding:7px 9px;cursor:pointer}.actions .save-question{border-color:#168653;background:#168653;color:#fff;font-weight:700}.order{font-weight:800;color:#168653}.danger{color:#a33!important}.check{flex-direction:row!important;align-items:center}.check input{width:auto}.choice-box{border:1px solid #e0e8e4;border-radius:9px;padding:12px;margin-bottom:12px}.choice-title{display:flex;justify-content:space-between;align-items:center}.choice-row{display:grid;grid-template-columns:1fr 1fr auto;gap:7px;margin:8px 0}.choice-box p{font-size:12px;color:#7b8d85}.actions{display:flex;gap:8px}.editor-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.editor-head .close{border:0;background:transparent;font-size:22px;color:#71847b;cursor:pointer}.notice{padding:10px 12px;background:#eaf8f0;border-radius:8px;margin-bottom:12px}.notice.error{background:#fff0f0;color:#9c2929}.empty,.empty-questions{background:#fff;border:1px dashed #ccd9d3;border-radius:12px;padding:24px;color:#74867e}.empty-questions{margin-bottom:10px;font-size:13px}@media(max-width:900px){.campaign-layout{grid-template-columns:1fr}.two,.question-detail dl{grid-template-columns:1fr}}</style>